actions.script:
const out = ec.service.sync().name('org.moqui.maps.MapServices.get#EffectiveConfig').requireNewTransaction(true)
    .parameters({profileId: profileId || null, layerIds: layerIds || null, adapterKey: adapterKey || null,
        recordKey: recordKey || null, addressPurpose: addressPurpose || null, routeApp: routeApp || null,
        locationShares: true}).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else {
    const config = out.config || {}
    ec.message.pushErrors()
    try {
        const found = ec.service.sync().name('org.moqui.maps.MapServices.find#Overlays').requireNewTransaction(true).call()
        // an overlay simplified on the server is drawn from its tiles once they are ready, and not drawn while they are made
        if (!ec.message.hasError()) config.layers = Array.from(config.layers || []).concat(Array.from(found?.overlayList || []).map(entry => ({
            id: entry.layerId, label: entry.label, kind: entry.tileUrl ? 'mvt' : 'geojson', url: entry.tileUrl || entry.url,
            maxZoom: entry.tilesMaxZoom, tilesStatus: entry.tilesStatus, tilesProgress: entry.tilesProgress, tilesNote: entry.tilesNote,
            visible: !(entry.tilesStatus && !entry.tileUrl), attribution: '', overlayId: entry.overlayId,
            isOwn: entry.isOwn, isPlaces: entry.isPlaces, ownerName: entry.ownerName, fileName: entry.fileName, path: entry.path,
            sourcePath: entry.sourcePath, formatEnumId: entry.formatEnumId, featureCount: entry.featureCount,
            rejectedCount: entry.rejectedCount, notes: entry.notes, bounds: entry.bounds})))
    } catch (err) {
        ec.logger.warn('Maps Browse: the overlays were not listed: ' + (err?.message ?? err))
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
    ec.web.sendJsonResponse(config)
}

ec.message.pushErrors()
try {
    const out = ec.resource.script('component://framework/service/org/moqui/maps/MapConfig.js').execute('liveShares', {})
    ec.web.sendJsonResponse({locationShares: Array.from(out.locationShares || [])})
} catch (err) {
    ec.logger.warn('Maps Browse: the location shares were not read: ' + (err?.message ?? err))
    ec.web.sendJsonResponse({errors: ec.l10n.localize('The location shares were not read')})
} finally { ec.message.clearErrors(); ec.message.popErrors() }

const me = ec.user.userId
const find = (entity) => ec.entity.find(entity).disableAuthz()
const ids = Array.from(new Set(Array.from(find('moqui.security.UserGroupMember').condition('userId', me)
    .conditionDate('fromDate', 'thruDate', null).selectField('userGroupId').list()).map((row) => row.userGroupId)))
    .filter((id) => id && id !== 'ALL_USERS')
const outside = new Set(ids.length ? Array.from(find('moqui.security.UserGroupPermission').condition('userGroupId', 'in', ids)
    .condition('userPermissionId', 'EXTERNAL_USER').conditionDate('fromDate', 'thruDate', null).selectField('userGroupId').list())
    .map((row) => row.userGroupId) : [])
const groups = ids.length ? Array.from(find('moqui.security.UserGroup').condition('userGroupId', 'in', ids.filter((id) => !outside.has(id)))
    .selectField('userGroupId,description').orderBy('description').list()).map((row) => ({userGroupId: row.userGroupId,
    label: row.description || row.userGroupId})) : []
const setting = (name, fallback) => { const n = Number(String(ec.factory.getConfValue('location@' + name) || '').trim()); return Number.isInteger(n) && n > 0 ? n : fallback }
const domain = String(ec.factory.getConfValue('xmpp-server@domain') || '').trim().toLowerCase()
const contacts = []
if (domain) {
    ec.message.pushErrors()
    try {
        const roster = ec.service.sync().name('org.moqui.chat.XmppServices.get#Roster').call() || {}
        const userIds = ec.message.hasError() ? [] : Array.from(roster.userIdList || [])
        if (userIds.length) for (const row of find('moqui.security.UserAccount').condition('userId', 'in', userIds)
                .selectField('userId,username,userFullName').orderBy('userFullName').list())
            if (row.username) contacts.push({jid: String(row.username).toLowerCase() + '@' + domain, label: row.userFullName || row.username})
    } catch (err) {
        ec.logger.warn('Maps Browse: the XMPP contacts were not listed: ' + (err?.message ?? err))
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
ec.web.sendJsonResponse({groups, xmpp: !!domain, contacts, maxShareHours: setting('max-share-hours', 24), trailMaxDays: setting('trail-max-days', 30)})

ec.message.pushErrors()
let found = []
try {
    const out = ec.service.sync().name('org.moqui.comms.CommsServices.search#Users').parameters({term: String(term || ''), limit: 12}).call() || {}
    if (!ec.message.hasError()) found = Array.from(out.userList || []).filter((user) => user.id !== ec.user.userId)
        .map((user) => ({value: user.id, label: user.label}))
} catch (err) {
    found = []
} finally { ec.message.clearErrors(); ec.message.popErrors() }
ec.web.sendJsonResponse(found)

let audienceList = null
try { audienceList = JSON.parse(String(context.audience || '[]')) } catch (err) { audienceList = null }
const thru = Number(context.thruDate)
const out = !Array.isArray(audienceList) ? null : ec.service.sync().name('org.moqui.maps.LocationServices.create#Share')
    .requireNewTransaction(true).parameters({audienceList: audienceList.slice(0, 100), thruDate: Number.isFinite(thru) ? new Date(thru) : null,
        precisionEnumId: String(context.precisionEnumId || 'LspExact'), keepTrail: String(context.keepTrail) === 'true',
        label: String(context.label || '').trim() || null}).call()
if (!out) ec.web.sendJsonResponse({applied: false, reason: ec.l10n.localize('Choose who sees your location')})
else if (ec.message.hasError()) { const reason = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({applied: false, reasonCode: out.reasonCode, reason}) }
else ec.web.sendJsonResponse({applied: true, shareId: out.shareId, thruDate: out.thruDate ? ec.user.timestampMillis(out.thruDate) : null,
    linkToken: out.linkToken || null})

const thru = Number(context.thruDate)
const out = ec.service.sync().name('org.moqui.maps.LocationServices.update#Share').requireNewTransaction(true)
    .parameters({shareId: String(shareId ?? ''), thruDate: Number.isFinite(thru) ? new Date(thru) : null}).call() || {}
if (ec.message.hasError()) { const reason = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({applied: false, reasonCode: out.reasonCode, reason}) }
else ec.web.sendJsonResponse({applied: true, thruDate: out.thruDate ? ec.user.timestampMillis(out.thruDate) : null})

const out = ec.service.sync().name('org.moqui.maps.LocationServices.update#Share').requireNewTransaction(true)
    .parameters({shareId: String(shareId ?? ''), addAudienceList: [{audienceTypeEnumId: 'LsaUserGroup', userGroupId: String(userGroupId ?? '')}]})
    .call() || {}
if (ec.message.hasError()) { const reason = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({applied: false, reasonCode: out.reasonCode, reason}) }
else ec.web.sendJsonResponse({applied: true, addedUserList: Array.from(out.addedUserList || [])})

const out = ec.service.sync().name('org.moqui.maps.LocationServices.stop#Share').requireNewTransaction(true)
    .parameters({shareId: String(shareId ?? '')}).call() || {}
if (ec.message.hasError()) { const reason = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({applied: false, reasonCode: out.reasonCode, reason}) }
else ec.web.sendJsonResponse({applied: true})

const out = ec.service.sync().name('org.moqui.maps.LocationServices.revoke#Audience').requireNewTransaction(true)
    .parameters({shareId: String(shareId ?? ''), audienceSeqId: String(audienceSeqId ?? '')}).call() || {}
if (ec.message.hasError()) { const reason = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({applied: false, reasonCode: out.reasonCode, reason}) }
else ec.web.sendJsonResponse({applied: true})

const out = ec.service.sync().name('org.moqui.maps.LocationServices.delete#Trail').requireNewTransaction(true)
    .parameters({shareId: String(shareId ?? '')}).call() || {}
if (ec.message.hasError()) { const reason = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({applied: false, reasonCode: out.reasonCode, reason}) }
else ec.web.sendJsonResponse({applied: true, deletedCount: Number(out.deletedCount) || 0})

const value = (name) => (context[name] == null ? null : String(context[name]).trim() || null)
const observed = Number(context.observedDate)
let answer = {statusCode: 500, reasonCode: 'FAILED'}
ec.message.pushErrors()
try {
    const out = ec.service.sync().name('org.moqui.maps.LocationServices.report#Position').requireNewTransaction(true)
        .parameters({shareId: String(shareId ?? ''), latitude: value('latitude'), longitude: value('longitude'), accuracy: value('accuracy'),
            heading: value('heading'), speed: value('speed'), observedDate: value('observedDate') && Number.isFinite(observed) ? new Date(observed) : null})
        .call() || {}
    answer = {statusCode: Number(out.statusCode) || (ec.message.hasError() ? 400 : 200), reasonCode: out.reasonCode || null,
        retryAfterSeconds: out.retryAfterSeconds == null ? null : Number(out.retryAfterSeconds)}
} catch (err) {
    // the failure's text may hold what was posted: it is not logged or answered
    answer = {statusCode: 500, reasonCode: 'FAILED'}
} finally { ec.message.clearErrors(); ec.message.popErrors() }
if (answer.statusCode === 200) {
    ec.message.pushErrors()
    try {
        const got = ec.service.sync().name('org.moqui.maps.LocationServices.get#Share').parameters({shareId: String(shareId ?? ''), trailPageSize: 1})
            .requireNewTransaction(true).call() || {}
        if (!ec.message.hasError() && got.latest) answer.latest = got.latest
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
ec.web.sendJsonResponse(answer)

const content = ec.service.sync().name('org.moqui.maps.MapServices.get#OverlayContent')
    .parameters({overlayId: String(overlayId ?? '')}).call()
if (ec.message.hasError() || !content?.ok) {
    const status = ec.message.hasError() ? 404 : Number(content.status) || 404
    ec.message.clearErrors()
    ec.web.sendJsonError(status, status === 422 ? String(content.reason || 'The overlay cannot be drawn') : 'Overlay not available')
} else ec.web.sendTextResponse(content.geojson, 'application/json', null)

const upload = context.overlayFile ?? null
const out = ec.service.sync().name('org.moqui.maps.MapServices.store#Overlay').requireNewTransaction(true)
    .parameters({file: upload && typeof upload === 'object' ? upload : null, driveId: driveId || null, path: path || null, label: label || null,
        generalize: String(context.generalize ?? '') === 'true'}).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else ec.web.sendJsonResponse({applied: out.applied, reasonCode: out.reasonCode, reason: out.reason, overlayId: out.overlayId,
    featureCount: out.featureCount, rejectedCount: out.rejectedCount, notes: out.notes || [], canGeneralize: out.canGeneralize === true,
    generalizing: out.generalizing === true})

const out = ec.service.sync().name('org.moqui.maps.MapServices.get#OverlayEdit').parameters({overlayId: String(overlayId ?? '')}).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else ec.web.sendJsonResponse({applied: out.applied === true, reasonCode: out.reasonCode, reason: out.reason, overlayId: out.overlayId,
    geojson: out.geojson, version: out.version, isPlaces: out.isPlaces === true, editPath: out.editPath, inPlace: out.inPlace === true})

const out = ec.service.sync().name('org.moqui.maps.MapServices.store#OverlayEdit').requireNewTransaction(true)
    .parameters({overlayId: String(overlayId ?? ''), geojson: String(context.geojson ?? ''), baseVersion: String(context.baseVersion ?? '')}).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else ec.web.sendJsonResponse({applied: out.applied === true, reasonCode: out.reasonCode, reason: out.reason, notes: out.notes || [],
    overlayId: out.overlayId, version: out.version, path: out.path, featureCount: out.featureCount})

const ids = String(context.overlayIds ?? '').split(',').map(id => id.trim()).filter(id => id)
const out = ec.service.sync().name('org.moqui.maps.MapSourceServices.get#OverlayTilesStatus').parameters({overlayIds: ids}).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else ec.web.sendJsonResponse({statusList: out.statusList || []})

const out = ec.service.sync().name('org.moqui.maps.MapSourceServices.cancel#OverlayTiles').requireNewTransaction(true)
    .parameters({overlayId: String(overlayId ?? '')}).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else ec.web.sendJsonResponse({applied: out.applied, reason: out.reason})

const out = ec.service.sync().name('org.moqui.maps.MapServices.delete#Overlay').requireNewTransaction(true)
    .parameters({overlayId: String(overlayId ?? '')}).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else ec.web.sendJsonResponse({applied: out.applied, reason: out.reason})

const overlayFile = row => row?.isDirectory === true || /\.(geojson|json|topojson|esrijson|gpx|kml|gml|wkt|wkb|csv|tsv|zip)$/i.test(String(row?.name || ''))
const out = ec.service.sync().name('org.moqui.comms.FilePickerServices.get#PickerData').parameter('recentLimit', 40)
    .requireNewTransaction(true).call()
if (ec.message.hasError()) { ec.message.clearErrors(); ec.web.sendJsonResponse({hasDrive: false, driveList: [], recentList: []}) }
else ec.web.sendJsonResponse({hasDrive: out.hasDrive, personalDriveId: out.personalDriveId, driveList: out.driveList || [],
    recentList: Array.from(out.recentList || []).filter(overlayFile)})

const overlayFile = row => row?.isDirectory === true || /\.(geojson|json|topojson|esrijson|gpx|kml|gml|wkt|wkb|csv|tsv|zip)$/i.test(String(row?.name || ''))
const out = ec.service.sync().name('org.moqui.comms.FilePickerServices.list#PickerFolder').parameters({driveId: driveId || '', path: path || ''})
    .requireNewTransaction(true).call()
if (ec.message.hasError()) { ec.message.clearErrors(); ec.web.sendJsonResponse({fileList: [], breadcrumbList: []}) }
else ec.web.sendJsonResponse({fileList: Array.from(out.fileList || []).filter(overlayFile), breadcrumbList: out.breadcrumbList || []})

const overlayFile = row => row?.isDirectory !== true && /\.(geojson|json|topojson|esrijson|gpx|kml|gml|wkt|wkb|csv|tsv|zip)$/i.test(String(row?.name || ''))
const out = ec.service.sync().name('org.moqui.comms.FilePickerServices.find#PickerFiles').parameters({text: text || '', limit: 50})
    .requireNewTransaction(true).call()
if (ec.message.hasError()) { ec.message.clearErrors(); ec.web.sendJsonResponse({fileList: []}) }
else ec.web.sendJsonResponse({fileList: Array.from(out.fileList || []).filter(overlayFile)})

const out = ec.service.sync().name('org.moqui.maps.MapServices.store#Place').requireNewTransaction(true)
    .parameters({label: label || '', longitude: longitude ?? '', latitude: latitude ?? ''}).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else ec.web.sendJsonResponse({applied: out.applied, reason: out.reason, placeId: out.placeId, overlayId: out.overlayId})

const out = ec.service.sync().name('org.moqui.maps.MapServices.delete#Place').requireNewTransaction(true)
    .parameters({placeId: String(placeId ?? '')}).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else ec.web.sendJsonResponse({applied: out.applied, reason: out.reason})

const out = ec.service.sync().name('org.moqui.maps.MapServices.find#SavedViews').requireNewTransaction(true)
    .parameters({profileId: profileId || null}).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else ec.web.sendJsonResponse({savedViewList: out.savedViewList || []})

const out = ec.service.sync().name('org.moqui.maps.MapServices.store#SavedView').requireNewTransaction(true)
    .parameters({description, isShared: isShared === 'Y' || isShared === 'true' ? 'Y' : 'N', profileId: profileId || null, view}).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else ec.web.sendJsonResponse({applied: out.applied, reasonCode: out.reasonCode, reason: out.reason, savedViewId: out.savedViewId})

const out = ec.service.sync().name('org.moqui.maps.MapServices.get#Preferences').requireNewTransaction(true).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else ec.web.sendJsonResponse({restoreLastView: !!out.preferences?.restoreLastView})

let settings = null
try { settings = JSON.parse(String(bands || 'null')) } catch (err) { settings = undefined }
const out = settings === undefined || !String(layerId || '').trim() ? null : ec.service.sync()
    .name('org.moqui.maps.MapServices.store#Preferences').requireNewTransaction(true)
    .parameters({rasters: {[String(layerId).trim()]: settings}}).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else if (!out) ec.web.sendJsonResponse({applied: false, reason: ec.l10n.localize('The band settings do not read')})
else ec.web.sendJsonResponse({applied: out.applied, reasonCode: out.reasonCode, reason: out.reason})

const term = String(q || '').trim().toLowerCase()
let postalCountries = null, postalCountryGeoId = null, geocoder = null, overture = null
const results = []
const overturePlaces = []
const geocoded = []
const sources = []
try {
    if (term) {
        const views = ec.service.sync().name('org.moqui.maps.MapServices.find#SavedViews').requireNewTransaction(true)
            .parameters({profileId: profileId || null}).call()
        sources.push('savedViews')
        for (const row of Array.from(views?.savedViewList || [])) {
            if (!String(row.description || '').toLowerCase().includes(term)) continue
            results.push({kind: 'savedView', id: 'view:' + row.savedViewId, savedViewId: row.savedViewId, label: row.description,
                sourceText: row.isOwn ? ec.l10n.localize('Your saved view') : ec.l10n.localize('Shared by') + ' ' + (row.ownerName || ''),
                view: row.view})
            if (results.length >= 50) break
        }
        const shown = ec.service.sync().name('org.moqui.maps.MapServices.get#EffectiveConfig').requireNewTransaction(true)
            .parameters({profileId: profileId || null, layerIds: layerIds || null, featuresExtent: extent || null}).call()
        sources.push('records')
        const layerLabels = Object.fromEntries(Array.from(shown?.config?.recordLayers || []).map(layer => [layer.id, layer.label]))
        for (const feature of Array.from(shown?.config?.features?.features || [])) {
            if (results.length >= 50) break
            const label = String(feature?.properties?.label || '')
            if (!label.toLowerCase().includes(term)) continue
            const coordinates = feature.geometry?.type === 'Point' ? feature.geometry.coordinates : null
            results.push({kind: 'record', id: 'record:' + feature.id, label, layerId: feature.properties.layerId,
                sourceText: layerLabels[feature.properties.layerId] || '', precisionEnumId: feature.properties.precisionEnumId || null,
                lon: coordinates ? coordinates[0] : null, lat: coordinates ? coordinates[1] : null})
        }
        // a postal code of a country (chosen, named in the text, or the user's): the local Geo data's postal
        // lookup (MapLookup.js searchPostal over get#PostalLocation), its results first, each with its source
        // and precision, and a code's several places as choices
        const postal = ec.resource.script('component://framework/service/org/moqui/maps/MapLookup.js')
            .execute('searchPostal', {q: String(q || ''), country: country || null})
        sources.push('postal')
        postalCountries = postal.countries
        postalCountryGeoId = postal.countryGeoId
        results.unshift(...Array.from(postal.results || []))
        // the user's saved places and those shared with them, before the postal codes
        const places = ec.resource.script('component://framework/service/org/moqui/maps/MapOverlays.js')
            .execute('searchPlaces', {q: String(q || ''), limit: 20})
        sources.push('places')
        results.unshift(...Array.from(places.results || []))
        // then the imported Overture places (plans/archive/Maps-Overture.md), local rows with their sources and licenses
        const overtureFound = ec.resource.script('component://framework/service/org/moqui/maps/OvertureData.js')
            .execute('searchPlaces', {q: String(q || ''), extent: extent || null, limit: 20})
        if (overtureFound.results && overtureFound.results.length) {
            sources.push('overture')
            overture = {attribution: overtureFound.attribution || ''}
            overturePlaces.push(...Array.from(overtureFound.results))
        }
        // last: the configured geocoder, only when one is enabled and tested and may be asked now (an outside one
        // with outside requests on; this server's own Overture address index while a region's addresses are active)
        const geocoders = ec.resource.script('component://framework/service/org/moqui/maps/MapGeocoders.js')
        if (geocoders.availability().available) {
            const found = ec.service.sync().name('org.moqui.maps.MapServices.find#Places').requireNewTransaction(true)
                .parameters({query: String(q || ''), countryGeoId: country || null, viewport: extent || null, limit: 10}).call()
            if (ec.message.hasError()) { ec.logger.warn('Maps search: the geocoder was not asked: ' + ec.message.getErrorsString()); ec.message.clearErrors() }
            else {
                sources.push('geocoder')
                geocoder = {providerName: found.providerName || '', attribution: found.attribution || '', ambiguous: !!found.ambiguous,
                    reasonCode: found.reasonCode || null, reason: found.reasonCode === 'NO_MATCH' ? null : (found.reason || null)}
                const sourceText = [found.providerName, found.attribution].filter(Boolean).join(' · ')
                Array.from(found.candidates || []).forEach((place, index) => geocoded.push({kind: 'geocoder', id: 'geocoder:' + index,
                    label: place.label, lon: place.lon, lat: place.lat, extent: place.extent || null, matchKind: place.matchKind,
                    precisionEnumId: place.precisionEnumId, precisionText: place.precisionText,
                    sourceText: place.sourceText ? [found.providerName, place.sourceText].filter(Boolean).join(' · ') : sourceText}))
            }
        }
    }
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    ec.web.sendJsonResponse({results: results.slice(0, 60).concat(overturePlaces, geocoded), sources, countries: postalCountries || [], countryGeoId: postalCountryGeoId || null,
        geocoder, overture})
} catch (err) {
    ec.message.clearErrors()
    ec.web.sendJsonResponse({errors: String(err.message || err)})
}

try {
    const config = ec.service.sync().name('org.moqui.maps.MapServices.get#EffectiveConfig').requireNewTransaction(true)
        .parameters({profileId: profileId || null, adapterKey: adapterKey || null, recordKey: recordKey || null,
            addressPurpose: addressPurpose || null}).call()?.config || {}
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    const views = ec.service.sync().name('org.moqui.maps.MapServices.find#SavedViews').requireNewTransaction(true).call()
    ec.message.clearErrors()
    // a precision as words, as the map-view's text modes give it
    const PRECISION = {GPP_USER_CONFIRMED: 'User-confirmed point', GPP_ADDRESS_MATCH: 'Address match',
        GPP_STREET_RANGE: 'Street-range interpolation', GPP_POSTAL_AREA: 'Postal-area representative point',
        GPP_PLACE_ESTIMATE: 'Place estimate'}
    const precision = id => PRECISION[id] ? ec.l10n.localize(PRECISION[id]) : ''
    const points = Array.from(config.points || []).map(point => Object.assign({}, point, {precision: precision(point.precisionEnumId)}))
    for (const feature of Array.from(config.features?.features || [])) {
        if (feature.geometry?.type !== 'Point') continue
        points.push({id: String(feature.id), lon: feature.geometry.coordinates[0], lat: feature.geometry.coordinates[1],
            label: feature.properties?.label || '', precision: precision(feature.properties?.precisionEnumId)})
    }
    // an extent's middle, across the antimeridian when west is greater than east (Russia), within -180 to 180
    const middle = (box) => {
        const [west, south, east, north] = box.map(Number), across = east < west ? east + 360 : east
        const lon = (west + across) / 2
        return [lon > 180 ? lon - 360 : lon, (south + north) / 2]
    }
    for (const row of Array.from(views?.savedViewList || []).slice(0, 100)) {
        const view = row.view || {}
        const center = Array.isArray(view.center) ? view.center : Array.isArray(view.extent) ? middle(view.extent) : null
        if (center) points.push({id: 'view:' + row.savedViewId, lon: center[0], lat: center[1], label: row.description,
            source: row.isOwn ? ec.l10n.localize('Your saved view') : ec.l10n.localize('Shared by') + ' ' + (row.ownerName || '')})
    }
    const notes = []
    // the user's saved places and those shared with them (read-only), and their overlays, own and shared; one that
    // fails to list leaves the rest as they are
    const overlays = []
    ec.message.pushErrors()
    try {
        const lists = ec.resource.script('component://framework/service/org/moqui/maps/MapOverlays.js')
        for (const place of Array.from(lists.execute('searchPlaces', {all: true, limit: 50}).results || []))
            points.push({id: place.id, lon: place.lon, lat: place.lat, label: place.label, precision: precision(place.precisionEnumId),
                source: place.isOwn ? place.sourceText : place.sourceText + ' · ' + ec.l10n.localize('read-only')})
        for (const entry of Array.from(lists.execute('findOverlays', {}).overlayList || [])) {
            const owner = entry.isOwn ? (entry.isPlaces ? ec.l10n.localize('Your places') : ec.l10n.localize('Yours'))
                : ec.l10n.localize('Shared by') + ' ' + (entry.ownerName || '') + ' · ' + ec.l10n.localize('read-only')
            overlays.push({label: entry.label, details: [owner, entry.featureCount + ' ' + ec.l10n.localize('features')].join(' · ')})
        }
    } catch (err) {
        ec.logger.warn('Maps terminal: the overlays and places were not listed: ' + (err?.message ?? err))
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
    // a postal search (postal: a code, with its country before or after it, "US 02134"): the local Geo data's
    // approximate places first (MapLookup.js searchPostal over get#PostalLocation), no outside request
    // its failure says so in its own words and leaves the rest of the map as it is
    let postalSearch = null
    if (String(postal || '').trim()) {
        const query = String(postal).trim().slice(0, 40)
        ec.message.pushErrors()
        try {
            const found = ec.resource.script('component://framework/service/org/moqui/maps/MapLookup.js')
                .execute('searchPostal', {q: query, country: null})
            if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
            const results = Array.from(found?.results || []).filter(result => result.lon != null && result.lat != null).slice(0, 20)
            points.unshift(...results.map((result, index) => ({id: 'postal:' + index, lon: Number(result.lon), lat: Number(result.lat),
                label: result.label, precision: result.precisionText || precision(result.precisionEnumId), source: result.sourceText || ''})))
            postalSearch = {query, count: results.length,
                reason: results.length ? (found?.reason || null) : (found?.reason || ec.l10n.localize('No imported Geo data has this postal code'))}
        } catch (err) {
            ec.logger.warn('Maps terminal: the postal search did not run: ' + (err?.message ?? err))
            postalSearch = {query, count: 0, reason: ec.l10n.localize('The postal search did not run')}
        } finally { ec.message.clearErrors(); ec.message.popErrors() }
    }
    if (config.profile?.notice?.text) notes.push(config.profile.notice.text)
    for (const error of Array.from(config.layerErrors || [])) notes.push(ec.l10n.localize('Not shown') + ': ' + error.label + ' (' + error.message + ')')
    if (config.featuresTruncated) notes.push(ec.l10n.localize('Only some of the records are shown: zoom in or search to narrow them'))
    const basemaps = Array.from(config.profile?.basemaps || [])
    const basemap = basemaps.find(entry => entry.id === config.profile?.basemap) || basemaps[0] || {}
    const attribution = String(basemap.attribution || '').split(/\n/).map(part => part.trim()).filter(part => part).join('; ')
    // the view Browse was opened on, as Browse.qvue takes it: a point (longitude, latitude, label: a dashboard
    // geomap's place, LocalMap's Open in Maps) marked first and centered on, else an area (extent: west,south,
    // east,north, west greater than east across the antimeridian: a geomap's country), its middle the center and
    // only the places within it listed (a postal search's places stay)
    let shown = points, center = config.center || null, area = config.extent || null
    const lonOk = lon => Number.isFinite(lon) && lon >= -180 && lon <= 180, latOk = lat => Number.isFinite(lat) && lat >= -90 && lat <= 90
    const givenLon = Number(longitude), givenLat = Number(latitude)
    const box = String(extent || '').split(',').map(value => value.trim() === '' ? NaN : Number(value))
    if (String(longitude ?? '').trim() && String(latitude ?? '').trim() && lonOk(givenLon) && latOk(givenLat)) {
        shown = [{id: 'given', lon: givenLon, lat: givenLat, label: String(label || '')}].concat(points)
        center = [givenLon, givenLat]
        area = null
    } else if (box.length === 4 && lonOk(box[0]) && lonOk(box[2]) && latOk(box[1]) && latOk(box[3]) && box[1] <= box[3]) {
        const [west, south, east, north] = box
        const within = point => {
            const lon = Number(point.lon), lat = Number(point.lat)
            return lat >= south && lat <= north && (west <= east ? lon >= west && lon <= east : lon >= west || lon <= east)
        }
        shown = points.filter(point => String(point.id).startsWith('postal:') || within(point))
        center = middle(box)
        area = box
    }
    ec.web.sendJsonResponse({points: shown, overlays, postalSearch, center, extent: area, notes,
        attribution: attribution || 'Natural Earth'})
} catch (err) {
    ec.message.clearErrors()
    ec.web.sendJsonResponse({errors: String(err.message || err)})
}
